INSERT INTO rubrics (case_id, criteria, descriptors, max_score, pass_score) VALUES (
  (SELECT id FROM cases WHERE slug = 'capital-raise-1'), '{"financial_analysis":20,"market_analysis":20,"risk_assessment":20,"recommendation":20}'::jsonb, '{"financial_analysis":"Must compute runway (cash ÷ net burn), the burn multiple (net burn ÷ net new ARR), and the implied dilution at the stated valuation. Credit answers that check whether growth justifies the burn rather than asserting it.","market_analysis":"Looks for comparison against sector benchmarks (Rule of 40, growth-adjusted burn), the funding environment, and what comparable companies raise at this stage.","risk_assessment":"Should identify down-round risk, the consequences of not raising, dilution to founders, and the sensitivity of runway to growth slowing.","recommendation":"Must commit to raise / don''t raise / raise a different amount, with a specific number and the trigger conditions that would change the answer."}'::jsonb, 80, 60
) ON CONFLICT (case_id) DO UPDATE SET
