  expected_framework = EXCLUDED.expected_framework, model_answer = EXCLUDED.model_answer,
  tags = EXCLUDED.tags, is_published = EXCLUDED.is_published, updated_at = now();

INSERT INTO rubrics (case_id, criteria, descriptors, max_score, pass_score) VALUES (
  (SELECT id FROM cases WHERE slug = 'npv-irr-project-4'), '{"financial_analysis":30,"assumptions":20,"risk_assessment":20,"recommendation":30}'::jsonb, '{"financial_analysis":"NPV must be computed with the correct discount rate and sign convention. Credit IRR and payback as supporting metrics, and penalise ranking projects on IRR alone when scale differs.","assumptions":"Should state assumptions about the discount rate, project life, and terminal/salvage value, and flag that sunk costs are irrelevant.","risk_assessment":"Expects a break-even or sensitivity view: what has to be true for NPV to go negative.","recommendation":"A go/no-go under capital rationing, with a clear ranking rule."}'::jsonb, 100, 60
) ON CONFLICT (case_id) DO UPDATE SET
  criteria = EXCLUDED.criteria, descriptors = EXCLUDED.descriptors,
