  (SELECT id FROM cases WHERE slug = 'statement-diagnosis-10'), '{"financial_analysis":30,"diagnosis":30,"risk_assessment":15,"recommendation":25}'::jsonb, '{"financial_analysis":"Expects the working capital cycle computed: DSO + DIO − DPO. Credit linking the income statement to the cash flow statement.","diagnosis":"The core insight is that a profitable company can run out of cash. The answer should identify where cash is trapped.","risk_assessment":"Covenant risk, supplier relationships, seasonality.","recommendation":"Specific levers with an estimate of the cash they release."}'::jsonb, 100, 60
