  (SELECT id FROM cases WHERE slug = 'comps-valuation-15'), '{"peer_selection":25,"multiple_analysis":25,"adjustments":20,"recommendation":30}'::jsonb, '{"peer_selection":"Should justify which comparables are genuinely comparable on growth, margin and risk — not just industry label.","multiple_analysis":"Expects EV/EBITDA and EV/Revenue applied correctly, with the bridge from enterprise value to equity value (subtract net debt).","adjustments":"Credit adjustments for size, growth, margin differential, liquidity and control premium.","recommendation":"A defensible valuation range with a point of view."}'::jsonb, 100, 60
