  (SELECT id FROM cases WHERE slug = 'market-sizing-10'), '{"structure":30,"assumptions":30,"arithmetic":20,"sense_check":20}'::jsonb, '{"structure":"A clear top-down or bottom-up tree, stated before any numbers are used.","assumptions":"Each assumption stated explicitly with a brief justification. This matters more than picking the ''right'' number.","arithmetic":"Clean, rounded, and correct.","sense_check":"A cross-check by a second method, or a comparison against a known reference point."}'::jsonb, 100, 60
) ON CONFLICT (case_id) DO UPDATE SET
  criteria = EXCLUDED.criteria, descriptors = EXCLUDED.descriptors,
