INSERT INTO rubrics (case_id, criteria, descriptors, max_score, pass_score) VALUES (
  (SELECT id FROM cases WHERE slug = 'market-entry-12'), '{"market_sizing":25,"competitive_analysis":20,"entry_mode":20,"risk_assessment":15,"recommendation":20}'::jsonb, '{"market_sizing":"Expects a bottom-up estimate with stated assumptions, not a cited figure. Credit sanity-checking top-down against bottom-up.","competitive_analysis":"Should assess incumbent strength, switching costs and likely competitive response.","entry_mode":"Organic vs acquisition vs partnership, with a reason tied to the specific barriers identified.","risk_assessment":"Regulatory, execution, cannibalisation, capital at risk.","recommendation":"A go/no-go with entry mode, sequencing and success metrics."}'::jsonb, 100, 60
