  (SELECT id FROM cases WHERE slug = 'retention-diagnosis-5'), '{"cohort_analysis":25,"root_cause":25,"solution_design":25,"measurement":25}'::jsonb, '{"cohort_analysis":"Must distinguish the shape of the retention curve — early drop-off versus a curve that never flattens — because they have different causes.","root_cause":"Should connect retention to whether users reached value, not to feature counts.","solution_design":"Interventions matched to the specific point of drop-off.","measurement":"A clear success metric and how it would be tested."}'::jsonb, 100, 60
) ON CONFLICT (case_id) DO UPDATE SET
