  (SELECT id FROM cases WHERE slug = 'growth-loop-14'), '{"growth_model":25,"loop_design":25,"quantitative_reasoning":25,"recommendation":25}'::jsonb, '{"growth_model":"Should model growth as a system with inputs and feedback, not a funnel with a bigger top.","loop_design":"Expects a specific loop with each step named, and an honest view of the viral coefficient.","quantitative_reasoning":"Must work with the CAC/LTV numbers given and compute payback.","recommendation":"A specific loop to build, with the metric that proves it works."}'::jsonb, 100, 60
) ON CONFLICT (case_id) DO UPDATE SET
