  (SELECT id FROM cases WHERE slug = 'product-launch-18'), '{"launch_strategy":25,"risk_management":25,"success_metrics":25,"recommendation":25}'::jsonb, '{"launch_strategy":"Expects a staged rollout with a rationale, not a date and a press release.","risk_management":"Should cover rollback plans, support readiness, and cannibalisation of the existing product.","success_metrics":"Leading and lagging indicators, with thresholds defined before launch.","recommendation":"A sequenced plan with go/no-go gates."}'::jsonb, 100, 60
) ON CONFLICT (case_id) DO UPDATE SET
